import selfies as sf
from rdkit import Chem
rx1='[O][=C][Branch1][C][O][C][N][C][=C][C][Branch1][C][F][=C][C][Branch1][C][Cl][=C][Ring1][Branch2]'
rx2='[C][=N][C][Branch1][#Branch2][N][C@@H1][C][C][C][N][C][Ring1][=Branch1][=C][C][=N][NH1][C][Ring1][Branch1][=N][Ring1][S]'
prod='[O][=C][Branch1][P][C][N][C][=C][C][Branch1][C][F][=C][C][Branch1][C][Cl][=C][Ring1][Branch2][N][C][C][C][C@@H1][Branch1][#C][N][C][=N][C][=N][C][NH1][N][=C][C][Ring1][=Branch2][=Ring1][Branch1][C][Ring1][S]'
for label,s in [('rx1',rx1),('rx2',rx2),('prod',prod)]:
    try:
        smi=sf.decoder(s)
        m=Chem.MolFromSmiles(smi)
        print(label, smi)
        print(Chem.MolToSmiles(m) if m else 'invalid')
        if m: print(Chem.MolToMolBlock(m))
    except Exception as e: print(label,'ERROR',repr(e))
